sp_theme_variant.css_variables:
$brand-primary:#428bca;
$body-bg:#fff;
$state-success-text:#5cb85c;
$sp-homepage-bg:#fff;
$sp-navbar-divider-color:#a64d63;
$text-color:#000000;
$sp-logo-margin-y:.5rem;
$navbar-inverse-link-hover-color:#6d737a;
$panel-bg:#fff;
$brand-success:#5cb85c;
$navbar-inverse-bg:#800020;
$brand-warning:#f0ad4e;
$brand-danger:#d9534f;
$sp-tagline-color:#717171;
$navbar-inverse-link-color:#efefef;
$brand-info:#5bc0de;
$link-color:#428bca;
$sp-logo-margin-x:1rem;
$btn-default-bg:#fff;
$text-muted:#979797;

.scrub-footer {
	hr {
    	border: .1rem solid $sp-navbar-divider-color !important;
	}
	.sf-main .sf-links-container .masonry-root .sf-menu.masonry-cell {
		border-left: .2rem solid $sp-navbar-divider-color;
		.sf-menu-label {
			color: $brand-info;
		}
	}
}

@media screen and (max-width: 635px) {
	.v5cf9e3234305ce107b228dc226b8f2a2 .scrub-footer {
    	.sf-main .sf-links-container .masonry-root .sf-menu.masonry-cell {
        	border-top: .2rem solid $sp-navbar-divider-color;
        }
    }
}

.panel-default .category-list .badge {
	background-color: $navbar-inverse-bg;
}
